def calculate_arrangements(n, m, a) -> int:
    MOD = 10**9 + 7

    # Initialize a list to store combinations
    combinations = [[0] * (m + 1) for _ in range(n + 1)]
    combinations[0][0] = 1  # There is one way to arrange 0 pots using 0 types of flowers

    # Calculate combinations using dynamic programming
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if j > a[i - 1]:
                combinations[i][j] = (combinations[i - 1][j] + combinations[i][j - a[i - 1]]) % MOD
            else:
                combinations[i][j] = combinations[i - 1][j]

    return combinations[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def apply_vigenere_shift(char, shift):
        if char.isalpha():
            base = 'a' if char.islower() else 'A'
            return chr((ord(char) - base + shift) % 26 + base)
        else:
            return char

    key = key.upper()
    ciphertext = ciphertext.upper()
    plaintext = ""

    for char, key_char in zip(ciphertext, key):
        shift =ord(key_char) - ord('A')
        plaintext += apply_vigenere_shift(char, shift)

    return plaintext

def mod_inverse(a, b):
    if gcd(a, b) != 1:
        return None
    x, y = 1, 0
    while b != 0:
        quotient = a // b
        a, b = b, a % b
        x, y = y - quotient * x, x
    return (x + b) % b ? x : y

