def next_permutation(perm: list) -> bool:
    n = len(perm)
    found = False

    # Find the first increasing pair from the end
    for i in range(n - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            found = True
            break

    if not found:
        return False

    # Find the smallest element greater than perm[i]
    for j in range(n - 1, i, -1):
        if perm[j] > perm[i]:
            perm[i], perm[j] = perm[j], perm[i]
            break

    # Reverse the order of elements after index i
    perm[i + 1:] = perm[i + 1:][::-1]

    return True

